/// A 2-D or 3-D heatmap overlay on anatomy.
#[derive(Debug, Clone)]
pub struct HeatmapOverlay {
    /// Scalar data (same layout as target geometry).
    pub data: Vec<f32>,
    /// Minimum value for normalization.
    pub min_val: f32,
    /// Maximum value for normalization.
    pub max_val: f32,
    /// Alpha multiplier.
    pub alpha: f32,
}
impl HeatmapOverlay {
    /// Create a new heatmap overlay.
    pub fn new(data: Vec<f32>, alpha: f32) -> Self {
        let min_val = data.iter().copied().fold(f32::INFINITY, f32::min);
        let max_val = data.iter().copied().fold(f32::NEG_INFINITY, f32::max);
        Self {
            data,
            min_val,
            max_val,
            alpha,
        }
    }
    /// Map a data index to a color using a hot colormap.
    pub fn color_at(&self, idx: usize) -> Rgba {
        if idx >= self.data.len() {
            return Rgba::transparent();
        }
        let v = self.data[idx];
        let t = if self.max_val > self.min_val {
            (v - self.min_val) / (self.max_val - self.min_val)
        } else {
            0.5
        };
        let t = clamp_f32(t, 0.0, 1.0);
        let r = clamp_f32(t * 3.0, 0.0, 1.0);
        let g = clamp_f32(t * 3.0 - 1.0, 0.0, 1.0);
        let b = clamp_f32(t * 3.0 - 2.0, 0.0, 1.0);
        Rgba::new(r, g, b, self.alpha)
    }
    /// Update data in place.
    pub fn update_data(&mut self, new_data: Vec<f32>) {
        self.min_val = new_data.iter().copied().fold(f32::INFINITY, f32::min);
        self.max_val = new_data.iter().copied().fold(f32::NEG_INFINITY, f32::max);
        self.data = new_data;
    }
}
/// An anatomy atlas mapping label values to named regions.
#[derive(Debug, Clone, Default)]
pub struct AnatomyAtlas {
    /// List of defined regions.
    pub regions: Vec<AtlasRegion>,
}
impl AnatomyAtlas {
    /// Create an empty atlas.
    pub fn new() -> Self {
        Self {
            regions: Vec::new(),
        }
    }
    /// Add a region.
    pub fn add_region(&mut self, region: AtlasRegion) {
        self.regions.push(region);
    }
    /// Find a region by label value.
    pub fn find_by_label(&self, label: u16) -> Option<&AtlasRegion> {
        self.regions.iter().find(|r| r.label == label)
    }
    /// Toggle visibility of a region by name.
    pub fn toggle_visibility(&mut self, name: &str) {
        for r in &mut self.regions {
            if r.name == name {
                r.visible = !r.visible;
            }
        }
    }
    /// Return color for a given label (transparent if not found or hidden).
    pub fn color_for_label(&self, label: u16) -> Rgba {
        self.find_by_label(label)
            .filter(|r| r.visible)
            .map(|r| r.color)
            .unwrap_or(Rgba::transparent())
    }
}
/// A simple ray-casting volume renderer.
///
/// Casts rays through the volume and composites RGBA samples using front-to-back
/// alpha blending.
#[derive(Debug, Clone)]
pub struct VolumeRenderer {
    /// Number of ray march steps.
    pub num_steps: usize,
    /// Early termination threshold on accumulated alpha.
    pub early_termination_alpha: f32,
}
impl VolumeRenderer {
    /// Create a new volume renderer.
    pub fn new(num_steps: usize) -> Self {
        Self {
            num_steps,
            early_termination_alpha: 0.99,
        }
    }
    /// Cast a ray through the volume and return the composited RGBA color.
    ///
    /// `ray_origin` and `ray_dir` are in fractional volume coordinates, where
    /// the volume fills the unit cube `[0, 1]^3`; `ray_dir` need not be
    /// normalised.  The ray is clipped against the cube and only the part
    /// inside it is marched, in [`VolumeRenderer::num_steps`] equal steps
    /// sampled at the middle of each step and composited front to back.  A ray
    /// that misses the volume, an empty volume, a zero direction and
    /// `num_steps == 0` all give [`Rgba::transparent`].
    ///
    /// Samples are normalised to `[0, 1]` with the value range of the whole
    /// volume (a constant volume maps to `0.5`) before they are looked up in
    /// `transfer`.  The alpha of the transfer function is the opacity of one
    /// nominal step, the cube edge divided by `num_steps`; it is corrected for
    /// the real step length (`1 - (1 - alpha)^(chord length)`), so a ray that
    /// crosses a shorter chord of the same material is correspondingly more
    /// transparent.
    ///
    /// The value range is computed once per call.  When many rays are cast
    /// through the same volume, compute [`VolumeData::value_range`] once and
    /// use [`VolumeRenderer::cast_ray_with_range`].
    pub fn cast_ray(
        &self,
        volume: &VolumeData,
        transfer: &ColorTransferFunc,
        ray_origin: [f32; 3],
        ray_dir: [f32; 3],
    ) -> Rgba {
        self.cast_ray_with_range(volume, transfer, volume.value_range(), ray_origin, ray_dir)
    }
    /// Like [`VolumeRenderer::cast_ray`], but normalises the samples with the
    /// caller-supplied `value_range = (min, max)` instead of scanning the
    /// volume, so the cost of a ray no longer depends on the volume size.
    pub fn cast_ray_with_range(
        &self,
        volume: &VolumeData,
        transfer: &ColorTransferFunc,
        value_range: (f32, f32),
        ray_origin: [f32; 3],
        ray_dir: [f32; 3],
    ) -> Rgba {
        let [nx, ny, nz] = volume.dims;
        if self.num_steps == 0 || nx == 0 || ny == 0 || nz == 0 {
            return Rgba::transparent();
        }
        let dir = normalize3f(ray_dir);
        let Some((t_near, t_far)) = ray_unit_cube_interval(ray_origin, dir) else {
            return Rgba::transparent();
        };
        let (min_value, max_value) = value_range;
        let span = max_value - min_value;
        let normalise = |scalar: f32| {
            if span > 0.0 && span.is_finite() {
                (scalar - min_value) / span
            } else {
                0.5
            }
        };
        let chord = t_far - t_near;
        let step = chord / self.num_steps as f32;
        let mut accumulated = Rgba::transparent();
        for i in 0..self.num_steps {
            let t = t_near + (i as f32 + 0.5) * step;
            let pos = [
                ray_origin[0] + dir[0] * t,
                ray_origin[1] + dir[1] * t,
                ray_origin[2] + dir[2] * t,
            ];
            let scalar = volume.sample(pos[0], pos[1], pos[2]);
            let sample_color = transfer.evaluate(normalise(scalar));
            let grad = volume.gradient(pos[0], pos[1], pos[2], step * 0.5);
            let grad_mag = norm3f(grad);
            let shading = if grad_mag > 1e-7 {
                let light = [0.577f32; 3];
                let n = normalize3f(grad);
                (dot3f(n, light).abs() * 0.8 + 0.2).clamp(0.0, 1.0)
            } else {
                1.0
            };
            // Opacity of this step relative to the nominal step 1 / num_steps:
            // step / nominal = chord.
            let alpha = 1.0 - (1.0 - clamp_unit(sample_color.a)).powf(chord);
            let shaded = Rgba::new(
                sample_color.r * shading,
                sample_color.g * shading,
                sample_color.b * shading,
                alpha,
            );
            // The samples get farther from the viewer as `t` grows, so the
            // accumulated colour is the front layer.
            accumulated = accumulated.blend_over(shaded);
            if accumulated.a > self.early_termination_alpha {
                break;
            }
        }
        accumulated
    }
}
