/// Maximum Intensity Projection renderer.
#[derive(Debug, Clone)]
pub struct MaximumIntensityProj {
    /// Number of ray steps.
    pub num_steps: usize,
}
impl MaximumIntensityProj {
    /// Create a new MIP renderer.
    pub fn new(num_steps: usize) -> Self {
        Self { num_steps }
    }
    /// Compute the MIP value along a ray.
    ///
    /// `ray_origin` and `ray_dir` are in fractional volume coordinates, where
    /// the volume fills the unit cube `[0, 1]^3`; `ray_dir` need not be
    /// normalised.  The ray is clipped against the cube and the part inside it
    /// is sampled at `num_steps + 1` equally spaced points that include the
    /// entry and the exit point.  A ray that misses the volume, a zero
    /// direction and `num_steps == 0` all return `0.0`.
    pub fn cast_ray(&self, volume: &VolumeData, ray_origin: [f32; 3], ray_dir: [f32; 3]) -> f32 {
        if self.num_steps == 0 {
            return 0.0;
        }
        let dir = normalize3f(ray_dir);
        let Some((t_near, t_far)) = ray_unit_cube_interval(ray_origin, dir) else {
            return 0.0;
        };
        let step = (t_far - t_near) / self.num_steps as f32;
        let mut max_val = f32::NAN;
        for i in 0..=self.num_steps {
            // The exit point is used as is so it is hit exactly.
            let t = if i == self.num_steps {
                t_far
            } else {
                t_near + i as f32 * step
            };
            let pos = [
                ray_origin[0] + dir[0] * t,
                ray_origin[1] + dir[1] * t,
                ray_origin[2] + dir[2] * t,
            ];
            // `f32::max` ignores a NaN sample.
            max_val = max_val.max(volume.sample(pos[0], pos[1], pos[2]));
        }
        if max_val.is_nan() { 0.0 } else { max_val }
    }
}
/// RGBA color with f32 components in `[0, 1]`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rgba {
    /// Red.
    pub r: f32,
    /// Green.
    pub g: f32,
    /// Blue.
    pub b: f32,
    /// Alpha.
    pub a: f32,
}
impl Rgba {
    /// Create a new RGBA color.
    pub fn new(r: f32, g: f32, b: f32, a: f32) -> Self {
        Self { r, g, b, a }
    }
    /// Transparent black.
    pub fn transparent() -> Self {
        Self::new(0.0, 0.0, 0.0, 0.0)
    }
    /// Opaque white.
    pub fn white() -> Self {
        Self::new(1.0, 1.0, 1.0, 1.0)
    }
    /// Pre-multiply alpha.
    pub fn pre_multiply_alpha(&self) -> Self {
        Self::new(self.r * self.a, self.g * self.a, self.b * self.a, self.a)
    }
    /// Blend this color over another (front-to-back compositing).
    pub fn blend_over(&self, bg: Rgba) -> Rgba {
        let a_out = self.a + bg.a * (1.0 - self.a);
        if a_out < 1e-7 {
            return Rgba::transparent();
        }
        Rgba::new(
            (self.r * self.a + bg.r * bg.a * (1.0 - self.a)) / a_out,
            (self.g * self.a + bg.g * bg.a * (1.0 - self.a)) / a_out,
            (self.b * self.a + bg.b * bg.a * (1.0 - self.a)) / a_out,
            a_out,
        )
    }
}
/// Standard pseudo-color palettes for medical imaging.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum PseudoColorMap {
    /// Greyscale (identity).
    Greyscale,
    /// Hot (black → red → yellow → white).
    Hot,
    /// Cool (cyan → magenta).
    Cool,
    /// Jet (blue → cyan → green → yellow → red).
    Jet,
    /// Spectral (rainbow).
    Spectral,
    /// Inferno (black → purple → orange → white).
    Inferno,
    /// Custom diverging (blue → white → red).
    DivergingBWR,
}
impl PseudoColorMap {
    /// Map a normalised value `t ∈ [0, 1]` to an RGBA color.
    pub fn map(&self, t: f32) -> Rgba {
        let t = clamp_f32(t, 0.0, 1.0);
        match self {
            PseudoColorMap::Greyscale => Rgba::new(t, t, t, 1.0),
            PseudoColorMap::Hot => Rgba::new(
                clamp_f32(t * 3.0, 0.0, 1.0),
                clamp_f32(t * 3.0 - 1.0, 0.0, 1.0),
                clamp_f32(t * 3.0 - 2.0, 0.0, 1.0),
                1.0,
            ),
            PseudoColorMap::Cool => Rgba::new(t, 1.0 - t, 1.0, 1.0),
            PseudoColorMap::Jet => {
                let r = clamp_f32(1.5 - (4.0 * t - 3.0).abs(), 0.0, 1.0);
                let g = clamp_f32(1.5 - (4.0 * t - 2.0).abs(), 0.0, 1.0);
                let b = clamp_f32(1.5 - (4.0 * t - 1.0).abs(), 0.0, 1.0);
                Rgba::new(r, g, b, 1.0)
            }
            PseudoColorMap::Spectral => {
                let r = clamp_f32((0.5 - (t - 0.5).abs()) * 4.0, 0.0, 1.0);
                let g = clamp_f32(1.0 - (t - 0.5).powi(2) * 8.0, 0.0, 1.0);
                let b = clamp_f32(1.0 - t * 2.0, 0.0, 1.0);
                Rgba::new(r, g, b, 1.0)
            }
            PseudoColorMap::Inferno => {
                let r = clamp_f32(t * t * 2.0, 0.0, 1.0);
                let g = clamp_f32(t * 0.8 - 0.1, 0.0, 1.0);
                let b = clamp_f32((1.0 - t) * t * 3.0, 0.0, 1.0);
                Rgba::new(r, g, b, 1.0)
            }
            PseudoColorMap::DivergingBWR => {
                if t < 0.5 {
                    let s = t * 2.0;
                    Rgba::new(s, s, 1.0, 1.0)
                } else {
                    let s = (t - 0.5) * 2.0;
                    Rgba::new(1.0, 1.0 - s, 1.0 - s, 1.0)
                }
            }
        }
    }
    /// Apply the colormap to a flat array of normalised values.
    pub fn apply_slice(&self, values: &[f32]) -> Vec<Rgba> {
        values.iter().map(|&v| self.map(v)).collect()
    }
}
/// Extended 2D measurement tool for slice-based operations.
#[derive(Debug, Clone, Default)]
pub struct PlanarMeasurementTool {
    /// History of planar measurements.
    pub history: Vec<PlanarMeasurement>,
}
impl PlanarMeasurementTool {
    /// Create a new planar measurement tool.
    pub fn new() -> Self {
        Self {
            history: Vec::new(),
        }
    }
    /// Measure pixel distance, converting to physical units via `pixel_spacing` (mm/px).
    pub fn measure_distance_2d(
        &mut self,
        a: [f64; 2],
        b: [f64; 2],
        pixel_spacing: [f64; 2],
    ) -> f64 {
        let dpx = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
        let dmm = ((b[0] * pixel_spacing[0] - a[0] * pixel_spacing[0]).powi(2)
            + (b[1] * pixel_spacing[1] - a[1] * pixel_spacing[1]).powi(2))
        .sqrt();
        self.history.push(PlanarMeasurement {
            kind: MeasurementKind::Distance,
            value_mm: dmm,
            value_px: dpx,
        });
        dmm
    }
    /// Measure angle at vertex in 2D (degrees).
    pub fn measure_angle_2d(&mut self, p1: [f64; 2], vertex: [f64; 2], p2: [f64; 2]) -> f64 {
        let v1 = [p1[0] - vertex[0], p1[1] - vertex[1]];
        let v2 = [p2[0] - vertex[0], p2[1] - vertex[1]];
        let n1 = (v1[0] * v1[0] + v1[1] * v1[1]).sqrt();
        let n2 = (v2[0] * v2[0] + v2[1] * v2[1]).sqrt();
        if n1 < 1e-10 || n2 < 1e-10 {
            return 0.0;
        }
        let cos_a = ((v1[0] * v2[0] + v1[1] * v2[1]) / (n1 * n2)).clamp(-1.0, 1.0);
        let ang = cos_a.acos().to_degrees();
        self.history.push(PlanarMeasurement {
            kind: MeasurementKind::Angle,
            value_mm: ang,
            value_px: ang,
        });
        ang
    }
    /// Measure polygon area (mm²) from a list of vertices.
    pub fn measure_area_polygon(&mut self, vertices: &[[f64; 2]], pixel_spacing: [f64; 2]) -> f64 {
        let n = vertices.len();
        if n < 3 {
            return 0.0;
        }
        let area_px: f64 = (0..n)
            .map(|i| {
                let a = vertices[i];
                let b = vertices[(i + 1) % n];
                a[0] * b[1] - b[0] * a[1]
            })
            .sum::<f64>()
            .abs()
            * 0.5;
        let area_mm2 = area_px * pixel_spacing[0] * pixel_spacing[1];
        self.history.push(PlanarMeasurement {
            kind: MeasurementKind::Volume,
            value_mm: area_mm2,
            value_px: area_px,
        });
        area_mm2
    }
}
/// A 3-D scalar field (e.g. CT/MRI voxels).
#[derive(Debug, Clone)]
pub struct VolumeData {
    /// Voxel data stored in row-major (z, y, x) order.
    pub data: Vec<f32>,
    /// Dimensions `[nx, ny, nz]`.
    pub dims: [usize; 3],
    /// Voxel spacing `[dx, dy, dz]` in mm.
    pub spacing: [f32; 3],
}
impl VolumeData {
    /// Create a new volume with given dimensions and spacing.
    pub fn new(dims: [usize; 3], spacing: [f32; 3]) -> Self {
        let n = dims[0] * dims[1] * dims[2];
        Self {
            data: vec![0.0f32; n],
            dims,
            spacing,
        }
    }
    /// Get the voxel value at (ix, iy, iz); positions outside the volume read
    /// as `0.0`.
    pub fn get(&self, ix: usize, iy: usize, iz: usize) -> f32 {
        let [nx, ny, nz] = self.dims;
        if ix >= nx || iy >= ny || iz >= nz {
            return 0.0;
        }
        self.data
            .get(iz * ny * nx + iy * nx + ix)
            .copied()
            .unwrap_or(0.0)
    }
    /// Set the voxel value at (ix, iy, iz); positions outside the volume are
    /// ignored.
    pub fn set(&mut self, ix: usize, iy: usize, iz: usize, value: f32) {
        let [nx, ny, nz] = self.dims;
        if ix >= nx || iy >= ny || iz >= nz {
            return;
        }
        if let Some(slot) = self.data.get_mut(iz * ny * nx + iy * nx + ix) {
            *slot = value;
        }
    }
    /// Trilinear interpolation at fractional coordinates `(fx, fy, fz)`.
    ///
    /// Each coordinate runs over `[0, 1]` from the first to the last voxel
    /// along its axis.  Coordinates outside that range are clamped to the
    /// volume boundary (so the edge voxels extend outwards), a NaN coordinate
    /// counts as `0`, and an empty volume (a zero dimension) samples as `0.0`.
    pub fn sample(&self, fx: f32, fy: f32, fz: f32) -> f32 {
        let [nx, ny, nz] = self.dims;
        if nx == 0 || ny == 0 || nz == 0 {
            return 0.0;
        }
        // Lower voxel, upper voxel and interpolation weight along one axis.
        let locate = |f: f32, n: usize| {
            let last = n - 1;
            let x = clamp_unit(f) * last as f32;
            let lower = (x.floor() as usize).min(last);
            (lower, (lower + 1).min(last), x - lower as f32)
        };
        let (ix, ix1, tx) = locate(fx, nx);
        let (iy, iy1, ty) = locate(fy, ny);
        let (iz, iz1, tz) = locate(fz, nz);
        let c000 = self.get(ix, iy, iz);
        let c100 = self.get(ix1, iy, iz);
        let c010 = self.get(ix, iy1, iz);
        let c110 = self.get(ix1, iy1, iz);
        let c001 = self.get(ix, iy, iz1);
        let c101 = self.get(ix1, iy, iz1);
        let c011 = self.get(ix, iy1, iz1);
        let c111 = self.get(ix1, iy1, iz1);
        lerp(
            lerp(lerp(c000, c100, tx), lerp(c010, c110, tx), ty),
            lerp(lerp(c001, c101, tx), lerp(c011, c111, tx), ty),
            tz,
        )
    }
    /// Compute the gradient at fractional coords using central differences.
    ///
    /// The stencil `[f - eps, f + eps]` of each axis is clipped to `[0, 1]`
    /// and the difference is divided by the width that is actually left, so
    /// at the boundary of the volume the result is a one-sided difference
    /// instead of an underestimate.  A zero (or non-finite) `eps` gives a zero
    /// gradient.
    pub fn gradient(&self, fx: f32, fy: f32, fz: f32, eps: f32) -> [f32; 3] {
        let (fx, fy, fz) = (clamp_unit(fx), clamp_unit(fy), clamp_unit(fz));
        let eps = if eps.is_finite() { eps.abs() } else { 0.0 };
        let derivative = |f: f32, value_at: &dyn Fn(f32) -> f32| {
            let lo = (f - eps).max(0.0);
            let hi = (f + eps).min(1.0);
            let width = hi - lo;
            if width > 0.0 {
                (value_at(hi) - value_at(lo)) / width
            } else {
                0.0
            }
        };
        [
            derivative(fx, &|x| self.sample(x, fy, fz)),
            derivative(fy, &|y| self.sample(fx, y, fz)),
            derivative(fz, &|z| self.sample(fx, fy, z)),
        ]
    }
    /// Minimum and maximum voxel values.
    pub fn value_range(&self) -> (f32, f32) {
        let mut mn = f32::INFINITY;
        let mut mx = f32::NEG_INFINITY;
        for &v in &self.data {
            if v < mn {
                mn = v;
            }
            if v > mx {
                mx = v;
            }
        }
        (mn, mx)
    }
}
/// A rendered CT slice (windowed, ready for display).
#[derive(Debug, Clone)]
pub struct CtSlice {
    /// Width in pixels.
    pub width: usize,
    /// Height in pixels.
    pub height: usize,
    /// Normalised pixel intensities in `[0, 1]`, row-major.
    pub pixels: Vec<f32>,
    /// Slice index (z position).
    pub slice_index: usize,
    /// CT window used.
    pub window: CtWindow,
}
impl CtSlice {
    /// Create a CT slice from raw HU data with a given window.
    pub fn from_hu(
        hu: Vec<f32>,
        width: usize,
        height: usize,
        slice_index: usize,
        window: CtWindow,
    ) -> Self {
        let pixels = window.apply_slice(&hu);
        Self {
            width,
            height,
            pixels,
            slice_index,
            window,
        }
    }
    /// Get normalised intensity at pixel (px, py).
    pub fn intensity_at(&self, px: usize, py: usize) -> f32 {
        if px >= self.width || py >= self.height {
            return 0.0;
        }
        self.pixels[py * self.width + px]
    }
    /// Convert pixel intensity to greyscale RGBA.
    pub fn to_rgba(&self) -> Vec<Rgba> {
        self.pixels
            .iter()
            .map(|&v| Rgba::new(v, v, v, 1.0))
            .collect()
    }
}
/// A single vessel segment in a vascular tree.
#[derive(Debug, Clone)]
pub struct VesselSegmentExt {
    /// Unique segment ID.
    pub id: u32,
    /// Parent segment ID (0 = root).
    pub parent_id: u32,
    /// Start point (mm).
    pub start: [f64; 3],
    /// End point (mm).
    pub end: [f64; 3],
    /// Radius at start (mm).
    pub radius_start: f64,
    /// Radius at end (mm).
    pub radius_end: f64,
    /// Vessel type.
    pub vessel_type: VesselTypeExt,
}
impl VesselSegmentExt {
    /// Create a vessel segment.
    pub fn new(
        id: u32,
        parent_id: u32,
        start: [f64; 3],
        end: [f64; 3],
        radius_start: f64,
        radius_end: f64,
        vessel_type: VesselTypeExt,
    ) -> Self {
        Self {
            id,
            parent_id,
            start,
            end,
            radius_start,
            radius_end,
            vessel_type,
        }
    }
    /// Segment length (mm).
    pub fn length(&self) -> f64 {
        let dx = self.end[0] - self.start[0];
        let dy = self.end[1] - self.start[1];
        let dz = self.end[2] - self.start[2];
        (dx * dx + dy * dy + dz * dz).sqrt()
    }
    /// Midpoint of segment.
    pub fn midpoint(&self) -> [f64; 3] {
        [
            0.5 * (self.start[0] + self.end[0]),
            0.5 * (self.start[1] + self.end[1]),
            0.5 * (self.start[2] + self.end[2]),
        ]
    }
    /// Mean radius.
    pub fn mean_radius(&self) -> f64 {
        0.5 * (self.radius_start + self.radius_end)
    }
    /// Volume of segment (truncated cone).
    pub fn volume(&self) -> f64 {
        let h = self.length();
        let r1 = self.radius_start;
        let r2 = self.radius_end;
        std::f64::consts::PI / 3.0 * h * (r1 * r1 + r1 * r2 + r2 * r2)
    }
    /// Display color based on vessel type.
    pub fn color(&self) -> [f32; 4] {
        match self.vessel_type {
            VesselTypeExt::Artery => [0.9, 0.1, 0.1, 1.0],
            VesselTypeExt::Vein => [0.1, 0.1, 0.8, 1.0],
            VesselTypeExt::Arteriole => [0.8, 0.3, 0.3, 1.0],
            VesselTypeExt::Venule => [0.3, 0.3, 0.8, 1.0],
            VesselTypeExt::Capillary => [0.7, 0.4, 0.7, 1.0],
            VesselTypeExt::Portal => [0.3, 0.7, 0.3, 1.0],
        }
    }
}
/// A vessel tree structure for centerline + branching rendering.
#[derive(Debug, Clone, Default)]
pub struct VesselTree {
    /// All segments (root = segment 0).
    pub segments: Vec<VesselSegment>,
}
impl VesselTree {
    /// Create a new vessel tree.
    pub fn new() -> Self {
        Self {
            segments: Vec::new(),
        }
    }
    /// Add a root segment (index 0).
    pub fn add_segment(&mut self, seg: VesselSegment) -> usize {
        let idx = self.segments.len();
        self.segments.push(seg);
        idx
    }
    /// Add a child segment to a parent.
    pub fn add_child(&mut self, parent: usize, seg: VesselSegment) -> usize {
        let idx = self.add_segment(seg);
        if parent < self.segments.len() {
            self.segments[parent].children.push(idx);
        }
        idx
    }
    /// Total number of segments.
    pub fn num_segments(&self) -> usize {
        self.segments.len()
    }
    /// Depth-first traversal returning segment indices in visit order.
    pub fn dfs_order(&self) -> Vec<usize> {
        if self.segments.is_empty() {
            return Vec::new();
        }
        let mut order = Vec::new();
        let mut stack = vec![0usize];
        while let Some(idx) = stack.pop() {
            if idx >= self.segments.len() {
                continue;
            }
            order.push(idx);
            for &child in self.segments[idx].children.iter().rev() {
                stack.push(child);
            }
        }
        order
    }
}
/// Tumor region descriptor for visualization.
#[derive(Debug, Clone)]
pub struct TumorRegion {
    /// Center in image coordinates (mm).
    pub center: [f64; 3],
    /// Principal radii \[ra, rb, rc\] (mm).
    pub radii: [f64; 3],
    /// Shape model.
    pub shape: TumorShapeModel,
    /// Enhancement value (0–1, from contrast imaging).
    pub enhancement: f64,
    /// ADC value (mm²/s) from DWI for characterization.
    pub adc: f64,
    /// Grade estimate (I–IV, 0 = unknown).
    pub grade: u8,
    /// Benign/malignant probability.
    pub malignancy_prob: f64,
}
impl TumorRegion {
    /// Create a spherical tumor.
    pub fn spherical(center: [f64; 3], radius: f64) -> Self {
        Self {
            center,
            radii: [radius; 3],
            shape: TumorShapeModel::Spherical,
            enhancement: 0.5,
            adc: 0.8e-3,
            grade: 0,
            malignancy_prob: 0.5,
        }
    }
    /// Volume of tumor region (mm³).
    pub fn volume(&self) -> f64 {
        (4.0 / 3.0) * std::f64::consts::PI * self.radii[0] * self.radii[1] * self.radii[2]
    }
    /// Check if a point is inside the tumor (ellipsoidal approximation).
    pub fn contains(&self, point: [f64; 3]) -> bool {
        let dx = (point[0] - self.center[0]) / self.radii[0];
        let dy = (point[1] - self.center[1]) / self.radii[1];
        let dz = (point[2] - self.center[2]) / self.radii[2];
        dx * dx + dy * dy + dz * dz <= 1.0
    }
    /// Generate isosurface vertices for a sphere (simplified).
    pub fn isosurface_vertices(&self, n_lat: usize, n_lon: usize) -> Vec<[f64; 3]> {
        let mut verts = Vec::new();
        for i in 0..=n_lat {
            let theta = std::f64::consts::PI * i as f64 / n_lat as f64;
            for j in 0..=n_lon {
                let phi = 2.0 * std::f64::consts::PI * j as f64 / n_lon as f64;
                let x = self.center[0] + self.radii[0] * theta.sin() * phi.cos();
                let y = self.center[1] + self.radii[1] * theta.sin() * phi.sin();
                let z = self.center[2] + self.radii[2] * theta.cos();
                verts.push([x, y, z]);
            }
        }
        verts
    }
}
/// Medical image measurement tool.
#[derive(Debug, Clone)]
pub struct MeasurementTool {
    /// History of performed measurements.
    pub history: Vec<Measurement>,
}
impl MeasurementTool {
    /// Create a new measurement tool.
    pub fn new() -> Self {
        Self {
            history: Vec::new(),
        }
    }
    /// Measure distance between two 3-D points (mm).
    pub fn measure_distance(&mut self, a: [f64; 3], b: [f64; 3]) -> f64 {
        let d = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2) + (b[2] - a[2]).powi(2)).sqrt();
        self.history.push(Measurement {
            kind: MeasurementKind::Distance,
            value: d,
        });
        d
    }
    /// Measure angle between two vectors at a vertex (degrees).
    pub fn measure_angle(&mut self, p1: [f64; 3], vertex: [f64; 3], p2: [f64; 3]) -> f64 {
        let v1 = [p1[0] - vertex[0], p1[1] - vertex[1], p1[2] - vertex[2]];
        let v2 = [p2[0] - vertex[0], p2[1] - vertex[1], p2[2] - vertex[2]];
        let n1 = (v1[0] * v1[0] + v1[1] * v1[1] + v1[2] * v1[2]).sqrt();
        let n2 = (v2[0] * v2[0] + v2[1] * v2[1] + v2[2] * v2[2]).sqrt();
        if n1 < 1e-10 || n2 < 1e-10 {
            return 0.0;
        }
        let cos_a = ((v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2]) / (n1 * n2)).clamp(-1.0, 1.0);
        let angle_deg = cos_a.acos().to_degrees();
        self.history.push(Measurement {
            kind: MeasurementKind::Angle,
            value: angle_deg,
        });
        angle_deg
    }
    /// Measure volume of a box region of interest (mm³).
    pub fn measure_voi(&mut self, min: [f64; 3], max: [f64; 3]) -> f64 {
        let vol = (max[0] - min[0]).abs() * (max[1] - min[1]).abs() * (max[2] - min[2]).abs();
        self.history.push(Measurement {
            kind: MeasurementKind::Volume,
            value: vol,
        });
        vol
    }
}
/// A collection of anatomical landmarks.
#[derive(Debug, Clone, Default)]
pub struct LandmarkSet {
    /// All landmarks.
    pub landmarks: Vec<AnatomicalLandmark>,
}
impl LandmarkSet {
    /// Create empty landmark set.
    pub fn new() -> Self {
        Self {
            landmarks: Vec::new(),
        }
    }
    /// Add a landmark.
    pub fn add(&mut self, lm: AnatomicalLandmark) {
        self.landmarks.push(lm);
    }
    /// Find landmarks within a radius of a point.
    pub fn within_radius(&self, center: [f64; 3], radius: f64) -> Vec<&AnatomicalLandmark> {
        self.landmarks
            .iter()
            .filter(|lm| {
                let d: f64 = lm
                    .position
                    .iter()
                    .zip(center.iter())
                    .map(|(a, b)| (a - b).powi(2))
                    .sum::<f64>()
                    .sqrt();
                d <= radius
            })
            .collect()
    }
    /// Count landmarks by type.
    pub fn count_by_type(&self, kind: LandmarkType) -> usize {
        self.landmarks
            .iter()
            .filter(|lm| lm.landmark_type == kind)
            .count()
    }
}
