/// Trocar port placement for laparoscopic procedures.
#[derive(Debug, Clone)]
pub struct TrocarPort {
    /// Port center position (mm).
    pub position: [f64; 3],
    /// Port diameter (mm).
    pub diameter: f64,
    /// Port orientation (unit vector of insertion axis).
    pub orientation: [f64; 3],
    /// Depth to target (mm).
    pub depth_to_target: f64,
    /// Port name/role.
    pub name: String,
}
impl TrocarPort {
    /// Create a trocar port.
    pub fn new(position: [f64; 3], diameter: f64, orientation: [f64; 3], name: &str) -> Self {
        Self {
            position,
            diameter,
            orientation,
            depth_to_target: 0.0,
            name: name.to_string(),
        }
    }
    /// Working volume: cone from port to target.
    pub fn working_cone_volume(&self) -> f64 {
        let r = 0.5 * self.diameter;
        let h = self.depth_to_target;
        std::f64::consts::PI * r * r * h / 3.0
    }
}
/// PET SUV image rendered with a medical-grade colormap.
#[derive(Debug, Clone)]
pub struct PetSuvImage {
    /// Width in pixels.
    pub width: usize,
    /// Height in pixels.
    pub height: usize,
    /// SUV values per pixel.
    pub suv_map: Vec<f64>,
    /// Colormap for display.
    pub colormap: PseudoColorMap,
    /// Maximum SUV for normalisation.
    pub suv_max: f64,
}
impl PetSuvImage {
    /// Create a PET SUV image from activity concentration data.
    pub fn from_activity(
        activity: &[f64],
        width: usize,
        height: usize,
        params: SuvParameters,
        colormap: PseudoColorMap,
    ) -> Self {
        let suv_map: Vec<f64> = activity.iter().map(|&a| params.suv_bw(a)).collect();
        let suv_max = suv_map
            .iter()
            .cloned()
            .fold(f64::NEG_INFINITY, f64::max)
            .max(1.0);
        Self {
            width,
            height,
            suv_map,
            colormap,
            suv_max,
        }
    }
    /// Get the RGBA color for pixel at (px, py).
    pub fn pixel_color(&self, px: usize, py: usize) -> Rgba {
        if px >= self.width || py >= self.height {
            return Rgba::transparent();
        }
        let suv = self.suv_map[py * self.width + px];
        let t = (suv / self.suv_max).min(1.0) as f32;
        self.colormap.map(t)
    }
    /// Render entire image to RGBA buffer.
    pub fn render(&self) -> Vec<Rgba> {
        (0..self.height)
            .flat_map(|py| (0..self.width).map(move |px| (px, py)))
            .map(|(px, py)| self.pixel_color(px, py))
            .collect()
    }
    /// Compute SUV_max over the entire image.
    pub fn compute_suv_max(&self) -> f64 {
        self.suv_map
            .iter()
            .cloned()
            .fold(f64::NEG_INFINITY, f64::max)
    }
    /// Compute SUV_mean (mean over non-zero voxels).
    pub fn compute_suv_mean(&self) -> f64 {
        let nonzero: Vec<f64> = self.suv_map.iter().cloned().filter(|&v| v > 0.0).collect();
        if nonzero.is_empty() {
            return 0.0;
        }
        nonzero.iter().sum::<f64>() / nonzero.len() as f64
    }
}
/// Isosurface renderer using Marching Cubes (single cube implementation).
#[derive(Debug, Clone)]
pub struct IsosurfaceRenderer {
    /// Iso value threshold.
    pub iso_value: f32,
}
impl IsosurfaceRenderer {
    /// Create a new isosurface renderer.
    pub fn new(iso_value: f32) -> Self {
        Self { iso_value }
    }
    /// Extract isosurface triangles from a single cube.
    ///
    /// `corner_values` are the scalar values at the 8 cube corners and
    /// `corner_positions` their positions, both in the marching-cubes corner
    /// order of [`crate::isosurface`] (corners 0-3 around the bottom face,
    /// 4-7 above them).  The cell is triangulated with the full 256-case
    /// tables of that module: a corner is *low* when its value is below
    /// `iso_value`, and the crossed edges are interpolated linearly.
    ///
    /// Returns at most 5 triangles.  Their vertices wind so that the face
    /// normal `(v1 - v0) x (v2 - v0)`, which is also stored for each vertex,
    /// points towards decreasing values, i.e. out of the region where the
    /// field is at least `iso_value`.  Zero-area triangles are dropped, and
    /// a cell with a non-finite corner value or iso value gives no triangles.
    pub fn marching_cube_triangles(
        &self,
        corner_values: [f32; 8],
        corner_positions: [[f32; 3]; 8],
    ) -> Vec<IsoTriangle> {
        let iso = self.iso_value;
        if !iso.is_finite() || corner_values.iter().any(|v| !v.is_finite()) {
            return Vec::new();
        }
        let case = corner_values
            .iter()
            .enumerate()
            .fold(0usize, |case, (corner, &value)| {
                if value < iso {
                    case | (1 << corner)
                } else {
                    case
                }
            });
        let crossed = EDGE_TABLE[case];
        if crossed == 0 {
            return Vec::new();
        }
        // Linear interpolation of the crossing on every crossed edge.  The end
        // corners of a crossed edge lie on different sides of `iso`, so their
        // values differ.
        let mut edge_points = [[0.0_f32; 3]; 12];
        for (edge, &(a, b)) in CUBE_EDGES.iter().enumerate() {
            if crossed & (1 << edge) == 0 {
                continue;
            }
            let t = (iso - corner_values[a]) / (corner_values[b] - corner_values[a]);
            let t = if t.is_nan() { 0.5 } else { t.clamp(0.0, 1.0) };
            edge_points[edge] =
                std::array::from_fn(|k| lerp(corner_positions[a][k], corner_positions[b][k], t));
        }
        let mut tris = Vec::new();
        for [a, b, c] in row_edge_triples(&TRI_TABLE[case]) {
            let (v0, v1, v2) = (edge_points[a], edge_points[b], edge_points[c]);
            let e1 = [v1[0] - v0[0], v1[1] - v0[1], v1[2] - v0[2]];
            let e2 = [v2[0] - v0[0], v2[1] - v0[1], v2[2] - v0[2]];
            let cross = [
                e1[1] * e2[2] - e1[2] * e2[1],
                e1[2] * e2[0] - e1[0] * e2[2],
                e1[0] * e2[1] - e1[1] * e2[0],
            ];
            // Normalise through the largest component so that very small or
            // very large cells neither underflow nor overflow; a zero-area
            // triangle has no normal and is skipped.
            let scale = cross.iter().fold(0.0_f32, |m, c| m.max(c.abs()));
            if !(scale > 0.0 && cross.iter().all(|c| c.is_finite())) {
                continue;
            }
            let scaled = [cross[0] / scale, cross[1] / scale, cross[2] / scale];
            let len = norm3f(scaled);
            let n = [scaled[0] / len, scaled[1] / len, scaled[2] / len];
            tris.push(IsoTriangle {
                vertices: [v0, v1, v2],
                normals: [n, n, n],
            });
        }
        tris
    }
}
/// Electrophysiology activation map on a cardiac mesh.
#[derive(Debug, Clone)]
pub struct ElectroPhysiology {
    /// Activation times per vertex (ms).
    pub activation_times: Vec<f32>,
    /// Current simulation time (ms).
    pub current_time: f32,
    /// Total activation cycle duration (ms).
    pub cycle_duration: f32,
}
impl ElectroPhysiology {
    /// Create a new activation map.
    pub fn new(activation_times: Vec<f32>, cycle_duration: f32) -> Self {
        Self {
            activation_times,
            current_time: 0.0,
            cycle_duration,
        }
    }
    /// Advance time by `dt` milliseconds.
    pub fn advance(&mut self, dt: f32) {
        self.current_time = (self.current_time + dt) % self.cycle_duration;
    }
    /// Compute the activation color at vertex `i`.
    ///
    /// Recently-activated vertices are red; resting is blue.
    pub fn vertex_color(&self, i: usize) -> Rgba {
        let at = if i < self.activation_times.len() {
            self.activation_times[i]
        } else {
            f32::INFINITY
        };
        let dt = (self.current_time - at).rem_euclid(self.cycle_duration);
        let t = clamp_f32(dt / 50.0, 0.0, 1.0);
        Rgba::new(1.0 - t, 0.0, t, 1.0)
    }
    /// Compute isochrone lines as pairs of vertex indices with matching activation time.
    pub fn isochrone_pairs(&self, iso_time: f32, tolerance: f32) -> Vec<(usize, usize)> {
        let n = self.activation_times.len();
        let mut pairs = Vec::new();
        for i in 0..n {
            for j in (i + 1)..n {
                let di = (self.activation_times[i] - iso_time).abs();
                let dj = (self.activation_times[j] - iso_time).abs();
                if di < tolerance && dj < tolerance {
                    pairs.push((i, j));
                }
            }
        }
        pairs
    }
}
